// Des: Tests for ZenRows login book: accounts, old file, limits
// Flo: scratch folder > write or save > load the book > pick accounts > errors for bad books
// I/O: scratch dir (no real secrets) > pass or fail (no leaks)
// Run: zig build test -Dfile=ut-secr-refz-test.zig
// ===================================================================
const std = @import("std"); const secr = @import("ut-secr-refz.zig");
fn dirOf(aren: std.mem.Allocator, tmpz: *std.testing.TmpDir) ![]u8 { return std.fmt.allocPrint(aren, ".zig-cache/tmp/{s}/secr", .{tmpz.sub_path}); }
fn put(aren: std.mem.Allocator, tmpz: *std.testing.TmpDir, name: []const u8, data: []const u8) ![]u8 { const dir = try dirOf(aren, tmpz); try std.Io.Dir.cwd().createDirPath(std.testing.io, dir); try std.Io.Dir.cwd().writeFile(std.testing.io, .{ .sub_path = try std.fmt.allocPrint(aren, "{s}/{s}", .{ dir, name }), .data = data }); return dir; }
test "save then load gives the same login; saving a second id adds an account and keeps the first" { var aren = std.heap.ArenaAllocator.init(std.testing.allocator); defer aren.deinit(); var tmpz = std.testing.tmpDir(.{}); defer tmpz.cleanup(); const dir = try dirOf(aren.allocator(), &tmpz); try secr.saveAcc(std.testing.io, aren.allocator(), dir, 3, "main", "a@b.test", "pw-1"); try secr.saveAcc(std.testing.io, aren.allocator(), dir, 3, "team2", "c@d.test", "pw-2"); const book = try secr.loadBook(aren.allocator(), std.testing.io, dir, 3); try std.testing.expectEqual(@as(usize, 2), book.accs.len); try std.testing.expectEqualStrings("main", book.main); const c1 = try secr.credFor(book, ""); try std.testing.expectEqualStrings("a@b.test", c1.user); const c2 = try secr.credFor(book, "team2"); try std.testing.expectEqualStrings("pw-2", c2.pass); try secr.saveAcc(std.testing.io, aren.allocator(), dir, 3, "team2", "c@d.test", "pw-3"); const b2 = try secr.loadBook(aren.allocator(), std.testing.io, dir, 3); try std.testing.expectEqual(@as(usize, 2), b2.accs.len); try std.testing.expectEqualStrings("pw-3", (try secr.credFor(b2, "team2")).pass); }
test "the limit and id rules apply to save; a missing, empty or unknown account gives NoSecret" { var aren = std.heap.ArenaAllocator.init(std.testing.allocator); defer aren.deinit(); var tmpz = std.testing.tmpDir(.{}); defer tmpz.cleanup(); const dir = try dirOf(aren.allocator(), &tmpz); try std.testing.expectError(error.BadUsage, secr.saveAcc(std.testing.io, aren.allocator(), dir, 3, "Bad Id", "u", "p")); try secr.saveAcc(std.testing.io, aren.allocator(), dir, 1, "a", "u", "p"); try std.testing.expectError(error.BadConfig, secr.saveAcc(std.testing.io, aren.allocator(), dir, 1, "b", "u", "p")); const book = try secr.loadBook(aren.allocator(), std.testing.io, dir, 1); try std.testing.expectError(error.NoSecret, secr.credFor(book, "zz")); const empty = try secr.loadBook(aren.allocator(), std.testing.io, "no-such-folder-zz", 3); try std.testing.expect(!empty.filez); try std.testing.expectError(error.NoSecret, secr.credFor(empty, "")); }
test "the old flat zr-login.json still loads as account main; the new file wins when both exist" { var aren = std.heap.ArenaAllocator.init(std.testing.allocator); defer aren.deinit(); var tmpz = std.testing.tmpDir(.{}); defer tmpz.cleanup(); const dir = try put(aren.allocator(), &tmpz, "zr-login.json", "{\"user\":\"old@x.test\",\"pass\":\"old-pw\"}"); const b1 = try secr.loadBook(aren.allocator(), std.testing.io, dir, 3); try std.testing.expectEqualStrings("old@x.test", (try secr.credFor(b1, "")).user); _ = try put(aren.allocator(), &tmpz, "user-acct.json", "{\"user\":\"new@x.test\",\"pass\":\"new-pw\"}"); const b2 = try secr.loadBook(aren.allocator(), std.testing.io, dir, 3); try std.testing.expectEqualStrings("new@x.test", (try secr.credFor(b2, "")).user); }
test "bad books are rejected: repeated id, bad id, too many, unknown main, caps percent out of range, broken JSON" { var aren = std.heap.ArenaAllocator.init(std.testing.allocator); defer aren.deinit(); var tmpz = std.testing.tmpDir(.{}); defer tmpz.cleanup(); const bads = [_][]const u8{ "{\"accs\":[{\"id\":\"a\"},{\"id\":\"a\"}]}", "{\"accs\":[{\"id\":\"A b\"}]}", "{\"accs\":[{\"id\":\"a\"},{\"id\":\"b\"},{\"id\":\"c\"}]}", "{\"main\":\"zz\",\"accs\":[{\"id\":\"a\"}]}", "{\"accs\":[{\"id\":\"a\",\"scal\":0}]}", "{\"accs\":[{\"id\":\"a\",\"scal\":101}]}", "oops" }; for (bads) |txt| { const dir = try put(aren.allocator(), &tmpz, "user-acct.json", txt); try std.testing.expectError(error.BadConfig, secr.loadBook(aren.allocator(), std.testing.io, dir, 2)); } }
test "id rules" { try std.testing.expect(secr.idOk("team-1")); try std.testing.expect(!secr.idOk("")); try std.testing.expect(!secr.idOk("Team")); try std.testing.expect(!secr.idOk("../x")); try std.testing.expect(!secr.idOk("a-very-long-id-over-16")); }
